/** Ordinary browser rule loading verifies versioned generated bytes; no client archive or private extraction cache is required. */
import {withEasterEgg} from '../domain/easter-egg.ts';
import registry from '../data/registry.json' with {type: 'json'};
import type {Rules} from './types.ts';

/** Deployment-aware runtime data endpoint, separate from original texture/sound resource endpoints. */
const BASE = (import.meta.env?.BASE_URL ?? '/') + 'rules/minecraft/26.3/';

/** Load the bounded rules and verify their hash and item-registry agreement before any gameplay consumer uses them.
 * @return {Promise<Rules>} Same-version rules without changing a save or discovering recipes.
 */
export async function loadRules(): Promise<Rules> {
    const response = await fetch(BASE + 'manifest.json');
    if (!response.ok) throw new Error('rule-resource-unavailable');
    const m = await response.json();
    if (m.version !== '26.3' || m.clientSha1 !== 'e877b6a07acd633fb3bb475002175cec036e7b87' || m.files?.length !== 1 || m.files[0].file !== 'rules.json') throw new Error('rule-version-mismatch');
    const r = await fetch(BASE + 'rules.json');
    if (!r.ok) throw new Error('rule-resource-unavailable');
    const bytes = await r.arrayBuffer(),
        hash = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), v => v.toString(16).padStart(2, '0')).join('');
    if (bytes.byteLength !== m.files[0].bytes || hash !== m.files[0].sha256) throw new Error('rule-integrity');
    const rules = JSON.parse(new TextDecoder().decode(bytes)) as Rules;
    if (Object.keys(rules.items).sort().join('|') !== [...registry].sort().join('|')) throw new Error('rule-registry-mismatch');
    return withEasterEgg(rules);
}
